package shop

import "testing"

func TestHeldoutTotalSkipsNonPositiveQty(t *testing.T) {
	c := Catalog{"a": {SKU: "a", Price: 250}, "b": {SKU: "b", Price: 100}}
	got, err := Total(c, []Line{{"a", 2}, {"b", 0}, {"b", -3}})
	if err != nil || got != 500 {
		t.Fatalf("Total = %d, %v; want 500, nil", got, err)
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc
